(125,'web_content_id46',NULL,NULL,'','','<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"color:#3333ff\"><strong><u>ตำแหน่งที่เปิดรับ</u></strong></span><br />\r\n&nbsp; &nbsp; &nbsp; &bull; วิศวกร / ช่างเขียนแบบ<br />\r\n&nbsp; &nbsp; &nbsp; &bull; ช่างประกอบ / ช่างไฟฟ้า / ช่างเชื่อม / ช่างกลึง / ช่าง CNC&nbsp;<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&bull; ช่างโลหะแผ่น (พับ&ndash;ตัด) / ช่างเจียแต่ง<br />\r\n&nbsp; &nbsp; &nbsp; &bull; พนักงานขับรถ 6 ล้อ<br />\r\n&nbsp; &nbsp; &nbsp; &bull; พนักงานบัญชี<br />\r\n&nbsp; &nbsp; &nbsp; &bull; พนักงานจัดซื้อ</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"color:#3333ff\"><u><strong>คุณสมบัติหลัก</strong></u></span><br />\r\n&nbsp; &nbsp; &nbsp; &bull; วุฒิ ปวส. &ndash; ปริญญาตรี หรือมีประสบการณ์</span><br />\r\n&nbsp;</p>\r\n\r\n<p><span style=\"color:#e74c3c\"><span style=\"font-size:20px\"><strong>*** ทำงาน จันทร์&ndash;เสาร์ เวลา 08.00&ndash;17.00 น.</strong></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"color:#3333ff\"><u><strong>สวัสดิการ</strong></u></span><br />\r\n&nbsp; &nbsp; &nbsp; &bull; ประกันสังคม<br />\r\n&nbsp; &nbsp; &nbsp; &bull; เบี้ยขยัน<br />\r\n&nbsp; &nbsp; &nbsp; &bull; เบี้ยเลี้ยงอาหารกลางวัน<br />\r\n&nbsp; &nbsp; &nbsp; &bull; พักร้อน<br />\r\n&nbsp; &nbsp; &nbsp; &bull; โบนัสประจำปี</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:20px\"><span style=\"color:#3333ff\"><strong><u>ติดต่อสมัครงาน</u></strong></span><br />\r\n&nbsp;02-902-5753-6</span></p>','',NULL,NULL);
